gml_scripts.file:
if (variable_instance_exists(id, "MurrayBody") && MurrayBody != noone && instance_exists(MurrayBody)) {
    instance_destroy(MurrayBody);
    MurrayBody = noone;
}
if (variable_instance_exists(id, "MurrayHead") && MurrayHead != noone && instance_exists(MurrayHead)) {
    instance_destroy(MurrayHead);
    MurrayHead = noone;
}
if (variable_instance_exists(id, "MurrayGlasses") && MurrayGlasses != noone && instance_exists(MurrayGlasses)) {
    instance_destroy(MurrayGlasses);
    MurrayGlasses = noone;
}

global.MurrayDeath = false;
MurrayBody = noone;
MurrayHead = noone;
MurrayGlasses = noone;
var ai = 20;
if (variable_global_exists("Murray_AI")) {
    ai = clamp(global.Murray_AI, 0, 20);
}
if (variable_global_exists("Murray_Disabled") && global.Murray_Disabled) {
    ai = 0;
}
if (ai == 0 && variable_global_exists("EndlessMode") && global.EndlessMode == true) {
    ai = 10;
} else if (ai == 0 && variable_global_exists("FourLayersDown") && global.FourLayersDown == true) {
    ai = 12;
}
if (ai <= 0) {
    instance_destroy();
    exit;
}
state = 0;
attack_timer = round(lerp(600, 320, ai / 20.0));
knock_timer = irandom_range(round(lerp(480, 180, ai / 20.0)), round(lerp(900, 360, ai / 20.0)));
has_glasses = true;
glasses_flying = false;
glasses_vx = 0;
glasses_vy = 0;
blind_fade = 0;
jumpscare_timer = 0;
jumpscare_frame = 0;
remove_cooldown = 0;
head_recoil_x = 0;
head_recoil_y = 0;
breath_timer = 0;
breath_alpha = 0.0;
glare_timer = 0;

if (state == 4) {
    var s_jump = asset_get_index("sMurray_Jumpscare");
    if (s_jump != -1) {
        var gw = display_get_gui_width();
        var gh = display_get_gui_height();
        var lunge_t = clamp(jumpscare_timer / 28.0, 0.0, 1.0);
        var lunge_curve = power(lunge_t, 0.45);
        var base_gui = max(gw / 640.0, gh / 360.0);
        var zoom_factor = lerp(0.50, 1.38, lunge_curve);
        var scale = base_gui * zoom_factor;
        var sw = 640.0 * scale;
        var start_x = gw * 0.12;
        var start_y = gh * 0.15;
        var cur_lunge_x = lerp(start_x, 0.0, lunge_curve);
        var cur_lunge_y = lerp(start_y, 0.0, lunge_curve);
        var shake_intensity = lerp(3.0, 13.0, lunge_curve) * (gw / 640.0);
        var shake_x = irandom_range(-round(shake_intensity), round(shake_intensity));
        var shake_y = irandom_range(-round(shake_intensity), round(shake_intensity));
        var head_sub = 1 + (floor(jumpscare_timer / 3) % 2);
        if (jumpscare_timer > 65) {
            head_sub = 2;
        }
        var jaw_snap = sin(jumpscare_timer * 1.8) * (5.5 * scale);
        var draw_x = ((gw - sw) / 2) + cur_lunge_x + shake_x;
        var draw_y = ((gh / 2) - (275.0 * scale)) + cur_lunge_y + shake_y;
        draw_sprite_ext(s_jump, 0, draw_x, draw_y, scale, scale, 0, c_white, 1);
        draw_sprite_ext(s_jump, head_sub, draw_x, draw_y + jaw_snap, scale, scale, 0, c_white, 1);
    }
}

var cx = 1456;
var cy = 1088;
var my_blind = instance_nearest(cx, cy, oWindowBlinds);
var deathcoined = false;
if (variable_global_exists("Murray_DeathCoined") && global.Murray_DeathCoined) deathcoined = true;
if (variable_global_exists("Murray_Disabled") && global.Murray_Disabled) deathcoined = true;
if (variable_global_exists("DeathCoin_Target") && global.DeathCoin_Target == "Murray") deathcoined = true;
if (state == 1 && mouse_check_button_pressed(mb_left)) {
    if (variable_global_exists("HeldItem") && (global.HeldItem == "DeathCoin" || global.HeldItem == "Death Coin" || global.HeldItem == "oShopItem_DeathCoin")) {
        deathcoined = true;
    }
}
if (deathcoined) {
    if (MurrayBody != noone && instance_exists(MurrayBody)) { instance_destroy(MurrayBody); MurrayBody = noone; }
    if (MurrayHead != noone && instance_exists(MurrayHead)) { instance_destroy(MurrayHead); MurrayHead = noone; }
    if (MurrayGlasses != noone && instance_exists(MurrayGlasses)) { instance_destroy(MurrayGlasses); MurrayGlasses = noone; }
    glasses_flying = false;
    var snd_dc = asset_get_index("sfxDeathCoin");
    if (snd_dc == -1) snd_dc = asset_get_index("sfxIgnitedFreddy_Hit1");
    if (snd_dc != -1) audio_play_sound(snd_dc, 10, false);
    global.Murray_DeathCoined = true;
    global.Murray_Disabled = true;
    instance_destroy();
    exit;
}
if (glasses_flying && MurrayGlasses != noone && instance_exists(MurrayGlasses)) {
    MurrayGlasses.x += glasses_vx;
    MurrayGlasses.y += glasses_vy;
    glasses_vy += 1.2;
    if (MurrayGlasses.y > 1300) {
        instance_destroy(MurrayGlasses);
        MurrayGlasses = noone;
        glasses_flying = false;
    }
}
if (state == 0) {
    if (MurrayBody != noone && instance_exists(MurrayBody)) { instance_destroy(MurrayBody); MurrayBody = noone; }
    if (MurrayHead != noone && instance_exists(MurrayHead)) { instance_destroy(MurrayHead); MurrayHead = noone; }
    if (MurrayGlasses != noone && instance_exists(MurrayGlasses)) { instance_destroy(MurrayGlasses); MurrayGlasses = noone; }
    glasses_flying = false;
    knock_timer--;
    if (knock_timer <= 0) {
        state = 1;
        var ai = 20;
        if (variable_global_exists("Murray_AI")) ai = clamp(global.Murray_AI, 0, 20);
        attack_timer = round(lerp(600, 320, ai / 20.0));
        has_glasses = true;
        remove_cooldown = 0;
        head_recoil_x = 0;
        head_recoil_y = 0;
        var spr_body = asset_get_index("sMurray_body");
        var spr_head = asset_get_index("sMurray_head");
        var spr_glasses = asset_get_index("sMurray_Glasses");
        MurrayBody = instance_create_layer(cx - 92, cy + 70, "Behind_Wall", oOfficeSprite);
        if (spr_body != -1) MurrayBody.sprite_index = spr_body;
        MurrayBody.DrawDepth = 48;
        MurrayHead = instance_create_layer(cx - 77, cy, "Behind_Wall", oOfficeSprite);
        if (spr_head != -1) MurrayHead.sprite_index = spr_head;
        MurrayHead.DrawDepth = 50;
        MurrayGlasses = instance_create_layer(cx - 77 + 52, cy + 48, "Behind_Wall", oOfficeSprite);
        if (spr_glasses != -1) MurrayGlasses.sprite_index = spr_glasses;
        MurrayGlasses.DrawDepth = 52;
        var snd = asset_get_index("snd_murray_knock");
        if (snd == -1) snd = asset_get_index("sfxKnock");
        if (snd == -1) snd = asset_get_index("snd_Knock");
        if (snd != -1) {
            audio_play_sound(snd, 10, false);
        } else if (file_exists("snd_murray_knock.ogg")) {
            var stream_k = audio_create_stream("snd_murray_knock.ogg");
            audio_play_sound(stream_k, 10, false);
        }
    }
}
if (state == 1) {
    var blind_closed = false;
    if (instance_exists(my_blind)) {
        if (!my_blind.Open) blind_closed = true;
    }
    if (!blind_closed) {
        attack_timer--;
    }
    if (remove_cooldown > 0) {
        remove_cooldown--;
    }
    head_recoil_x = lerp(head_recoil_x, 0, 0.15);
    head_recoil_y = lerp(head_recoil_y, 0, 0.15);
    var torso_bob = sin(current_time * 0.003) * 2.0;
    if (MurrayBody != noone && instance_exists(MurrayBody)) {
        MurrayBody.y = (cy + 70) + torso_bob;
    }
    if (MurrayHead != noone && instance_exists(MurrayHead)) {
        var head_bob = sin(current_time * 0.004) * 2.5;
        var jitter_x = has_glasses ? 0 : random_range(-1.2, 1.2);
        var jitter_y = has_glasses ? 0 : random_range(-1.2, 1.2);
        MurrayHead.x = (cx - 77) + head_recoil_x + jitter_x;
        MurrayHead.y = cy + head_bob + head_recoil_y + jitter_y;
        if (has_glasses && MurrayGlasses != noone && instance_exists(MurrayGlasses)) {
            MurrayGlasses.x = MurrayHead.x + 52;
            MurrayGlasses.y = MurrayHead.y + 48;
        }
    }
    var hover_murray = false;
    if (instance_exists(o3DMouse)) {
        if (point_distance(cx, cy + 70, o3DMouse.x, o3DMouse.y) < 180) hover_murray = true;
    }
    var flashing = false;
    if (keyboard_check(ord("F")) || mouse_check_button(mb_right)) flashing = true;
    if (variable_global_exists("Flashlight") && global.Flashlight) flashing = true;
    if (variable_global_exists("flashlight") && global.flashlight) flashing = true;
    if (has_glasses && flashing && !blind_closed && hover_murray) {
        attack_timer = max(20, attack_timer - 1);
    }
    var remove_pressed = mouse_check_button_pressed(mb_right) || keyboard_check_pressed(ord("G")) || keyboard_check_pressed(ord("E")) || (hover_murray && mouse_check_button_pressed(mb_left));
    var blinds_flash_shock = (blind_closed && flashing);
    if (has_glasses && (remove_pressed || blinds_flash_shock)) {
        has_glasses = false;
        glasses_flying = true;
        glasses_vx = choose(-6, 6);
        glasses_vy = -8;
        remove_cooldown = 20;
        head_recoil_x = (glasses_vx > 0 ? 14 : -14);
        head_recoil_y = -7;
        var spr_scare = asset_get_index("sMurray_head_Scare");
        if (spr_scare != -1 && MurrayHead != noone && instance_exists(MurrayHead)) {
            MurrayHead.sprite_index = spr_scare;
        }
        var snd_click = asset_get_index("sfxClick");
        if (snd_click == -1) snd_click = asset_get_index("snd_Button");
        if (snd_click != -1) audio_play_sound(snd_click, 10, false);
        var snd_v = asset_get_index("snd_murray_voice");
        if (snd_v != -1) {
            audio_play_sound(snd_v, 10, false);
        } else if (file_exists("snd_murray_voice.ogg")) {
            var stream_v = audio_create_stream("snd_murray_voice.ogg");
            audio_play_sound(stream_v, 10, false);
        }
    }
    if (!has_glasses && !blind_closed && flashing && remove_cooldown <= 0 && hover_murray) {
        state = 2;
        blind_fade = 60;
        if (MurrayBody != noone && instance_exists(MurrayBody)) {
            instance_destroy(MurrayBody);
            MurrayBody = noone;
        }
        if (MurrayGlasses != noone && instance_exists(MurrayGlasses)) {
            instance_destroy(MurrayGlasses);
            MurrayGlasses = noone;
        }
        glasses_flying = false;
        var spr_flash = asset_get_index("sMurray_Flash");
        if (MurrayHead != noone && instance_exists(MurrayHead)) {
            if (spr_flash != -1) MurrayHead.sprite_index = spr_flash;
            MurrayHead.x = cx - 94;
            MurrayHead.y = cy;
            MurrayHead.DrawDepth = 54;
        }
        var snd_hit = asset_get_index("sfxIgnitedFreddy_Hit1");
        if (snd_hit == -1) snd_hit = asset_get_index("sfxFlash");
        if (snd_hit != -1) audio_play_sound(snd_hit, 10, false);
        var snd_v = asset_get_index("snd_murray_voice");
        if (snd_v != -1) {
            audio_play_sound(snd_v, 10, false);
        } else if (file_exists("snd_murray_voice.ogg")) {
            var stream_v = audio_create_stream("snd_murray_voice.ogg");
            audio_play_sound(stream_v, 10, false);
        }
    }
    if (attack_timer <= 0 && !blind_closed) {
        state = 4;
        jumpscare_timer = 0;
        jumpscare_frame = 0;
        glasses_flying = false;
        if (MurrayBody != noone && instance_exists(MurrayBody)) { instance_destroy(MurrayBody); MurrayBody = noone; }
        if (MurrayHead != noone && instance_exists(MurrayHead)) { instance_destroy(MurrayHead); MurrayHead = noone; }
        if (MurrayGlasses != noone && instance_exists(MurrayGlasses)) { instance_destroy(MurrayGlasses); MurrayGlasses = noone; }
        var scream = asset_get_index("sfxJumpscareNormal");
        if (scream == -1) scream = asset_get_index("sfxWindowScare");
        if (scream != -1) audio_play_sound(scream, 10, false);
    }
}
if (state == 2) {
    blind_fade--;
    if (blind_fade <= 0) {
        state = 0;
        var ai = 20;
        if (variable_global_exists("Murray_AI")) ai = clamp(global.Murray_AI, 0, 20);
        knock_timer = irandom_range(round(lerp(1800, 600, ai / 20.0)), round(lerp(2800, 1000, ai / 20.0)));
        if (MurrayHead != noone && instance_exists(MurrayHead)) {
            instance_destroy(MurrayHead);
            MurrayHead = noone;
        }
    }
}
if (state == 4) {
    jumpscare_timer++;
    jumpscare_frame = (floor(jumpscare_timer / 4) % 3);
    if (jumpscare_timer >= 85) {
        global.MurrayDeath = true;
        global.Jumpscare = -1;
        var r_go = asset_get_index("GameOver");
        if (r_go != -1) room_goto(r_go);
        else game_restart();
    }
}

depth = -1000;
if (!variable_global_exists("Murray_AI")) {
    global.Murray_AI = 0;
}
if (!variable_global_exists("CustomNight_Page")) {
    global.CustomNight_Page = 0;
}
btn_vanilla_x = 340;
btn_vanilla_y = 324;
btn_vanilla_w = 126;
btn_vanilla_h = 28;
btn_back_x = 306;
btn_back_y = 13;
btn_back_w = 150;
btn_back_h = 18;
tile_x = 28;
tile_y = 48;
card_x = 88;
card_y = 46;
card_w = 368;
card_h = 142;
btn_m1_x = card_x + 204;
btn_p1_x = card_x + 240;
btn_0_x  = card_x + 284;
btn_20_x = card_x + 320;
btn_ai_y = card_y + 114;
btn_ai_w = 32;
btn_ai_h = 20;
prev_freddy_ai = -1;

var fnt = asset_get_index("fnt_Small");
if (fnt == -1) fnt = asset_get_index("fnt_Dialogue");
if (fnt != -1) draw_set_font(fnt);
if (global.CustomNight_Page == 0) {
    var hov_van = (mouse_x >= btn_vanilla_x && mouse_x <= btn_vanilla_x + btn_vanilla_w && mouse_y >= btn_vanilla_y && mouse_y <= btn_vanilla_y + btn_vanilla_h);
    draw_set_color(hov_van ? make_color_rgb(230, 230, 230) : make_color_rgb(205, 205, 205));
    draw_rectangle(btn_vanilla_x, btn_vanilla_y, btn_vanilla_x + btn_vanilla_w, btn_vanilla_y + btn_vanilla_h, false);
    if (hov_van && mouse_check_button(mb_left)) {
        draw_set_color(make_color_rgb(80, 80, 80));
        draw_line(btn_vanilla_x, btn_vanilla_y, btn_vanilla_x + btn_vanilla_w, btn_vanilla_y);
        draw_line(btn_vanilla_x, btn_vanilla_y, btn_vanilla_x, btn_vanilla_y + btn_vanilla_h);
        draw_set_color(c_white);
        draw_line(btn_vanilla_x, btn_vanilla_y + btn_vanilla_h, btn_vanilla_x + btn_vanilla_w, btn_vanilla_y + btn_vanilla_h);
        draw_line(btn_vanilla_x + btn_vanilla_w, btn_vanilla_y, btn_vanilla_x + btn_vanilla_w, btn_vanilla_y + btn_vanilla_h);
    } else {
        draw_set_color(c_white);
        draw_line(btn_vanilla_x, btn_vanilla_y, btn_vanilla_x + btn_vanilla_w, btn_vanilla_y);
        draw_line(btn_vanilla_x, btn_vanilla_y, btn_vanilla_x, btn_vanilla_y + btn_vanilla_h);
        draw_set_color(make_color_rgb(80, 80, 80));
        draw_line(btn_vanilla_x, btn_vanilla_y + btn_vanilla_h, btn_vanilla_x + btn_vanilla_w, btn_vanilla_y + btn_vanilla_h);
        draw_line(btn_vanilla_x + btn_vanilla_w, btn_vanilla_y, btn_vanilla_x + btn_vanilla_w, btn_vanilla_y + btn_vanilla_h);
    }
    draw_set_color(c_black);
    draw_rectangle(btn_vanilla_x - 1, btn_vanilla_y - 1, btn_vanilla_x + btn_vanilla_w + 1, btn_vanilla_y + btn_vanilla_h + 1, true);
    draw_set_halign(fa_center);
    draw_set_valign(fa_middle);
    draw_text(btn_vanilla_x + (btn_vanilla_w / 2), btn_vanilla_y + (btn_vanilla_h / 2), "MODDED (1) >");
}
else if (global.CustomNight_Page == 1) {
    draw_set_color(make_color_rgb(175, 175, 175));
    draw_rectangle(0, 0, 474, 360, false);
    var win_x = 10;
    var win_y = 10;
    var win_w = 454;
    var win_h = 340;
    draw_set_color(make_color_rgb(198, 198, 198));
    draw_rectangle(win_x, win_y, win_x + win_w, win_y + win_h, false);
    draw_set_color(c_white);
    draw_line(win_x, win_y, win_x + win_w, win_y);
    draw_line(win_x, win_y, win_x, win_y + win_h);
    draw_set_color(make_color_rgb(60, 60, 60));
    draw_line(win_x, win_y + win_h, win_x + win_w, win_y + win_h);
    draw_line(win_x + win_w, win_y, win_x + win_w, win_y + win_h);
    draw_set_color(c_black);
    draw_rectangle(win_x - 1, win_y - 1, win_x + win_w + 1, win_y + win_h + 1, true);
    draw_set_color(make_color_rgb(0, 0, 128));
    draw_rectangle(win_x + 3, win_y + 3, win_x + win_w - 3, win_y + 24, false);
    draw_set_color(c_white);
    draw_set_halign(fa_left);
    draw_set_valign(fa_middle);
    draw_text(win_x + 8, win_y + 13, "MODDED ANIMATRONICS - ROSTER (PAGE 1)");
    var hov_back = (mouse_x >= btn_back_x && mouse_x <= btn_back_x + btn_back_w && mouse_y >= btn_back_y && mouse_y <= btn_back_y + btn_back_h);
    draw_set_color(hov_back ? make_color_rgb(230, 230, 230) : make_color_rgb(205, 205, 205));
    draw_rectangle(btn_back_x, btn_back_y, btn_back_x + btn_back_w, btn_back_y + btn_back_h, false);
    draw_set_color(hov_back && mouse_check_button(mb_left) ? make_color_rgb(80, 80, 80) : c_white);
    draw_line(btn_back_x, btn_back_y, btn_back_x + btn_back_w, btn_back_y);
    draw_line(btn_back_x, btn_back_y, btn_back_x, btn_back_y + btn_back_h);
    draw_set_color(hov_back && mouse_check_button(mb_left) ? c_white : make_color_rgb(80, 80, 80));
    draw_line(btn_back_x, btn_back_y + btn_back_h, btn_back_x + btn_back_w, btn_back_y + btn_back_h);
    draw_line(btn_back_x + btn_back_w, btn_back_y, btn_back_x + btn_back_w, btn_back_y + btn_back_h);
    draw_set_color(c_black);
    draw_rectangle(btn_back_x - 1, btn_back_y - 1, btn_back_x + btn_back_w + 1, btn_back_y + btn_back_h + 1, true);
    draw_set_halign(fa_center);
    draw_set_valign(fa_middle);
    draw_set_color(c_black);
    draw_text(btn_back_x + (btn_back_w / 2), btn_back_y + (btn_back_h / 2), "< VANILLA ROSTER");
    draw_set_halign(fa_left);
    draw_set_valign(fa_top);
    draw_set_color(make_color_rgb(50, 50, 50));
    draw_text(win_x + 10, win_y + 28, "Adjust AI difficulty (0-20). Click tile, arrows, scroll wheel or quick buttons.");
    var spr_base = asset_get_index("sTileBase");
    if (spr_base != -1) draw_sprite(spr_base, 0, tile_x, tile_y);
    var spr_murray = asset_get_index("sTile_Murray");
    if (spr_murray != -1) {
        var is_dc = false;
        if (variable_global_exists("Murray_DeathCoined") && global.Murray_DeathCoined) is_dc = true;
        if (variable_global_exists("Murray_Disabled") && global.Murray_Disabled) is_dc = true;
        if (global.Murray_AI > 0 && !is_dc) {
            draw_sprite(spr_murray, 0, tile_x, tile_y);
        } else {
            var spr_off = asset_get_index("sTile_Murray_1");
            if (spr_off != -1) {
                draw_sprite(spr_off, 0, tile_x, tile_y);
            } else if (sprite_get_number(spr_murray) > 1) {
                draw_sprite(spr_murray, 1, tile_x, tile_y);
            } else {
                draw_sprite_ext(spr_murray, 0, tile_x, tile_y, 1, 1, 0, make_color_rgb(130, 130, 130), 0.75);
            }
        }
    }
    var spr_arrows = asset_get_index("sCustomNightArrows");
    if (spr_arrows != -1) draw_sprite(spr_arrows, 0, tile_x, tile_y + 48);
    var spr_counter = asset_get_index("sCustomNightCounter");
    if (spr_counter != -1) draw_sprite(spr_counter, global.Murray_AI, tile_x + 16, tile_y + 48);
    draw_set_color(make_color_rgb(240, 240, 240));
    draw_rectangle(card_x, card_y, card_x + card_w, card_y + card_h, false);
    draw_set_color(make_color_rgb(120, 120, 120));
    draw_line(card_x, card_y, card_x + card_w, card_y);
    draw_line(card_x, card_y, card_x, card_y + card_h);
    draw_set_color(c_white);
    draw_line(card_x, card_y + card_h, card_x + card_w, card_y + card_h);
    draw_line(card_x + card_w, card_y, card_x + card_w, card_y + card_h);
    draw_set_color(c_black);
    draw_set_halign(fa_left);
    draw_set_valign(fa_top);
    draw_text(card_x + 8, card_y + 6, "MURRAY MOOSE");
    draw_set_halign(fa_right);
    if (global.Murray_AI > 0) {
        draw_set_color(make_color_rgb(0, 130, 0));
        draw_text(card_x + card_w - 8, card_y + 6, "[ ACTIVE - AI " + string(global.Murray_AI) + " ]");
    } else {
        draw_set_color(make_color_rgb(120, 120, 120));
        draw_text(card_x + card_w - 8, card_y + 6, "[ INACTIVE - AI 0 ]");
    }
    draw_set_halign(fa_left);
    draw_set_color(make_color_rgb(60, 60, 60));
    draw_text(card_x + 8, card_y + 22, "Location: Back Left Office Window");
    draw_set_color(c_black);
    draw_text_ext(card_x + 8, card_y + 38, "Acecha en la ventana trasera izquierda. Cuando aparezca su cara en el cristal, bajale la persiana o haz clic sobre el para arrancarle las gafas de sol. Alumbralo con la persiana abierta para ahuyentarlo.", 13, card_w - 16);
    draw_set_color(make_color_rgb(170, 20, 20));
    draw_text(card_x + 8, card_y + 118, "Immune to flashlight until sunglasses are removed.");
    var qb_x = [btn_m1_x, btn_p1_x, btn_0_x, btn_20_x];
    var qb_txt = ["-1", "+1", "0", "20"];
    for (var bi = 0; bi < 4; bi++) {
        var bx = qb_x[bi];
        var by = btn_ai_y;
