void UpdateSpriteTexture(string spriteName, string[] filePaths)
{
    try
    {
        UndertaleSprite spr = Data.Sprites.ByName(spriteName);
        if (spr != null)
        {
            for (int f = 0; f < spr.Textures.Count && f < filePaths.Length; f++)
            {
                string path = filePaths[f];
                if (File.Exists(path))
                {
                    using MagickImage img = TextureWorker.ReadBGRAImageFromFile(path);
                    var item = spr.Textures[f].Texture;
                    if (item != null)
                    {
                        if ((int)img.Width != item.TargetWidth || (int)img.Height != item.TargetHeight)
                        {
                            img.Resize((uint)item.TargetWidth, (uint)item.TargetHeight);
                        }
                        MainThreadAction(() => { item.ReplaceTexture(img); });
                    }
                }
            }
        }
    }
    catch (Exception)
    {
    }
}
